func TestAdd(t *testing.T) {
	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestClamp(t *testing.T) {
	tests := []struct {
		name   string
		value  int
		lower  int
		upper  int
		want   int
	}{
		{name: "below lower bound", value: -5, lower: 0, upper: 10, want: 0},
		{name: "above upper bound", value: 15, lower: 0, upper: 10, want: 10},
		{name: "within bounds", value: 5, lower: 0, upper: 10, want: 5},
		{name: "equal to lower bound", value: 0, lower: 0, upper: 10, want: 0},
		{name: "equal to upper bound", value: 10, lower: 0, upper: 10, want: 10},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := clamp(tt.value, tt.lower, tt.upper); got != tt.want {
				t.Fatalf("clamp(%d, %d, %d) = %d, want %d", tt.value, tt.lower, tt.upper, got, tt.want)
			}
		})
	}
}

